schema_ddl:
CREATE TABLE clienti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    telefono TEXT,
    citta TEXT NOT NULL,
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE ordini (
    id INT PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_ordine TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    importo_totale NUMERIC(12,2) NOT NULL CHECK (importo_totale >= 0),
    stato TEXT NOT NULL CHECK (stato IN ('in_attesa', 'pagato', 'spedito', 'consegnato', 'annullato'))
);

CREATE INDEX idx_ordini_cliente_id ON ordini(cliente_id);
CREATE INDEX idx_ordini_data_ordine ON ordini(data_ordine);
